import{_ as o,c as n,o as a,aj as d}from"./chunks/framework.Id7s26SP.js";const p=JSON.parse('{"title":"Interface: Db3Index","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/Db3Index.md","filePath":"reference/js-bao-wss-client/api/interfaces/Db3Index.md"}'),t={name:"reference/js-bao-wss-client/api/interfaces/Db3Index.md"};function r(i,e,c,s,l,h){return a(),n("div",null,[...e[0]||(e[0]=[d('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / Db3Index</p><h1 id="interface-db3index" tabindex="-1">Interface: Db3Index <a class="header-anchor" href="#interface-db3index" aria-label="Permalink to “Interface: Db3Index”">​</a></h1><p>One index on a db3&#39;s records, as <code>client.db3.indexes.list</code> returns it.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="annmodel" tabindex="-1">annModel? <a class="header-anchor" href="#annmodel" aria-label="Permalink to “annModel?”">​</a></h3><blockquote><p><code>optional</code> <strong>annModel?</strong>: <a href="./Db3IndexAnnModel.html"><code>Db3IndexAnnModel</code></a></p></blockquote><p>An <code>ann</code> vector index&#39;s shared model, once a device uploaded one: every device holding the db3 installs it rather than training its own. Absent until then, and on any other kind.</p><hr><h3 id="fields" tabindex="-1">fields <a class="header-anchor" href="#fields" aria-label="Permalink to “fields”">​</a></h3><blockquote><p><strong>fields</strong>: <code>string</code>[]</p></blockquote><p>The fields, in index order.</p><hr><h3 id="generation" tabindex="-1">generation? <a class="header-anchor" href="#generation" aria-label="Permalink to “generation?”">​</a></h3><blockquote><p><code>optional</code> <strong>generation?</strong>: <code>number</code></p></blockquote><p>A vector index&#39;s generation: new at every registration, so an index dropped and registered again, or registered in a db3 created again under a deleted one&#39;s id, never takes an older model. Absent on any other kind.</p><hr><h3 id="kind" tabindex="-1">kind? <a class="header-anchor" href="#kind" aria-label="Permalink to “kind?”">​</a></h3><blockquote><p><code>optional</code> <strong>kind?</strong>: <a href="./../type-aliases/Db3IndexKind.html"><code>Db3IndexKind</code></a></p></blockquote><p>What the index is: <code>members</code> exactly when <code>members</code> is <code>true</code>.</p><hr><h3 id="members" tabindex="-1">members? <a class="header-anchor" href="#members" aria-label="Permalink to “members?”">​</a></h3><blockquote><p><code>optional</code> <strong>members?</strong>: <code>boolean</code></p></blockquote><p><code>true</code> for a string-set field&#39;s member index, which serves <code>$contains</code>, any-of, membership levels and unfiltered facets on the field in the db3. Absent on any other index.</p><hr><h3 id="model" tabindex="-1">model <a class="header-anchor" href="#model" aria-label="Permalink to “model”">​</a></h3><blockquote><p><strong>model</strong>: <code>string</code></p></blockquote><p>The model whose records the index covers.</p><hr><h3 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to “name”">​</a></h3><blockquote><p><strong>name</strong>: <code>string</code></p></blockquote><p>The index&#39;s name: <code>idx_records_&lt;model&gt;_&lt;field&gt;</code> for a field&#39;s shared index, <code>idx_uc_&lt;model&gt;_&lt;constraint&gt;</code> for a declared compound constraint, <code>idx_named_&lt;model&gt;_&lt;name&gt;</code> for one registered with a name, <code>idx_members_&lt;model&gt;_&lt;field&gt;</code> for a string-set field&#39;s member index, <code>idx_text_&lt;model&gt;</code> for a model&#39;s text index, <code>idx_vec_&lt;model&gt;_&lt;field&gt;</code> for a vector index.</p><hr><h3 id="on" tabindex="-1">on? <a class="header-anchor" href="#on" aria-label="Permalink to “on?”">​</a></h3><blockquote><p><code>optional</code> <strong>on?</strong>: <a href="./../type-aliases/Db3IndexPlacement.html"><code>Db3IndexPlacement</code></a></p></blockquote><p>Where the index lives. A declared field&#39;s index is on <code>both</code>; every index of a db3 that lives only on this device is on <code>device</code>.</p><hr><h3 id="origins" tabindex="-1">origins <a class="header-anchor" href="#origins" aria-label="Permalink to “origins”">​</a></h3><blockquote><p><strong>origins</strong>: <a href="./Db3IndexOrigin.html"><code>Db3IndexOrigin</code></a>[]</p></blockquote><p>Every origin keeping the index. It is dropped when the last one goes.</p><hr><h3 id="revision" tabindex="-1">revision? <a class="header-anchor" href="#revision" aria-label="Permalink to “revision?”">​</a></h3><blockquote><p><code>optional</code> <strong>revision?</strong>: <code>number</code></p></blockquote><p>A vector index&#39;s model revision: 1, and moved on when its model is deleted. Absent on any other kind.</p><hr><h3 id="text" tabindex="-1">text? <a class="header-anchor" href="#text" aria-label="Permalink to “text?”">​</a></h3><blockquote><p><code>optional</code> <strong>text?</strong>: <a href="./Db3TextIndex.html"><code>Db3TextIndex</code></a></p></blockquote><p>A text index&#39;s options, every one filled in. Absent on any other kind.</p><hr><h3 id="unique" tabindex="-1">unique <a class="header-anchor" href="#unique" aria-label="Permalink to “unique”">​</a></h3><blockquote><p><strong>unique</strong>: <code>boolean</code></p></blockquote><p>Whether uniqueness is enforced: true while any origin asks for it.</p><hr><h3 id="vector" tabindex="-1">vector? <a class="header-anchor" href="#vector" aria-label="Permalink to “vector?”">​</a></h3><blockquote><p><code>optional</code> <strong>vector?</strong>: <a href="./Db3VectorIndex.html"><code>Db3VectorIndex</code></a></p></blockquote><p>A vector index&#39;s options, filled in (<code>distance</code> <code>cos</code> and <code>index</code><code>&quot;exact&quot;</code> when not registered), with its field&#39;s <code>dims</code> and <code>element</code>. Absent on any other kind.</p>',57)])])}const m=o(t,[["render",r]]);export{p as __pageData,m as default};
